class AppError(Exception):
    def __init__(self, message, code=1):
        super().__init__(message)
        self.message = message
        self.code = code


def merge_ranges(ranges):
    out = []
    for a, b in sorted(set(ranges)):
        if b <= a:
            continue
        if out and a <= out[-1][1]:
            out[-1] = (out[-1][0], max(b, out[-1][1]))
        else:
            out.append((a, b))
    return out


def subtract_ranges(ranges, exclusions):
    result = []
    exclusions = merge_ranges(exclusions)
    for a, b in merge_ranges(ranges):
        for x, y in exclusions:
            if y <= a:
                continue
            if x >= b:
                break
            if x > a:
                result.append((a, x))
            a = max(a, y)
        if a < b:
            result.append((a, b))
    return result
