"""Command-line interface and recursive file processing."""
import os
import sys
import stat
import re
import fnmatch
import difflib
from datetime import datetime,timezone
from pathlib import Path
from common import AppError
from scopes import LANG_SCOPES
from rx import Regex
from actions import unescape_replacement
from engine import apply_text

