ENUMS={'stdin-detection':['auto','force-readable','force-unreadable'],'stdout-detection':['auto','force-tty','force-pipe'],'completions':['bash','elvish','fish','powershell','zsh']}
ENV_BOOL=set('upper lower titlecase normalize squeeze invert literal-string german-naive german-prefer-original'.split())
COMPOSABLE=['upper','lower','titlecase','normalize','german','symbols']


def display(name):
    if name in LANG_SCOPES:return '--'+name+' <'+name.upper()+'>'
    if name.endswith('-query-file'):return '--'+name+' <TREE-SITTER-QUERY-FILENAME>'
    if name.endswith('-query'):return '--'+name+' <TREE-SITTER-QUERY-VALUE>'
    if name in VALUES:return '--'+name+' <'+('SHELL' if name=='completions' else name.upper().replace('-','_'))+'>'
    return '--'+name


def cli_error(body,usage=None):
    raise AppError('error: '+body+'\n\n'+(usage+'\n\n' if usage else '')+TRAILER,2)


def choices(name):
    if name in LANG_SCOPES:return [x for x in LANG_SCOPES[name].split() if '~' not in x]
    return ENUMS.get(name,[])


def validate_value(name,value):
    if name in LANG_SCOPES or name in ENUMS:
        opts=choices(name)
        if name in LANG_SCOPES and '~' in value:
            base,pat=value.split('~',1)
