            body="invalid value '"+value+"' for '"+display(name)+"'\n  [possible values: "+', '.join(opts)+']'
            similar=difflib.get_close_matches(value,opts,n=1,cutoff=.6)
            if similar:body+="\n\n  tip: a similar value exists: '"+similar[0]+"'"
            cli_error(body)
    if name=='threads':
        reason=None
