    stamp=datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.%fZ')
    sys.stderr.write('['+stamp+' '+level+' srgn] '+message+'\n')


def stdin_readable(opts):
    how=opts.get('stdin-detection','auto')
    if how=='force-readable':return True
    if how=='force-unreadable':return False
    try:
        mode=os.fstat(0).st_mode
        return stat.S_ISFIFO(mode) or stat.S_ISREG(mode) or stat.S_ISSOCK(mode)
    except OSError:return False


def glob_match(path,pat):
    if fnmatch.fnmatchcase(path,pat):return True
    if pat.startswith('./'):pat=pat[2:]
    if fnmatch.fnmatchcase(path,pat):return True
    if '**/' in pat and fnmatch.fnmatchcase(path,pat.replace('**/','')):return True
    # Paths are relative, unless the caller explicitly supplied an absolute glob.
    if pat.startswith('/') and fnmatch.fnmatchcase(os.path.abspath(path),pat):return True
    return False


def discover(opts):
    extensions={'python':('.py','.pyi'),'rust':('.rs',),'go':('.go',),'c':('.c','.h'),'csharp':('.cs',),'typescript':('.ts','.tsx'),'hcl':('.tf','.hcl','.tfvars')}
    lang=opts['scopes'][0][0] if opts['scopes'] else None
    pattern=opts.get('glob')
    if not lang and not pattern:return []
    if pattern:
        # Glob syntax rejects mismatched bracket ranges and malformed recursive globs.
        if pattern.count('[')>pattern.count(']'):
            raise AppError('Error: Invalid glob pattern\n')
    ignores=[];found=[]
    root='.'
    if pattern and os.path.isabs(pattern):
        pre=re.split(r'[?*\[]',pattern,1)[0]
        root=pre if os.path.isdir(pre) else os.path.dirname(pre)
        if not root:root='/'
    # Ignore-file support is active with repository metadata present, as in the walker.
    gitroot=Path.cwd()
    havegit=any((p/'.git').exists() for p in [gitroot]+list(gitroot.parents))
    for base,dirs,files in os.walk(root,followlinks=False):
        relbase=os.path.relpath(base,'.')
        if not opts.get('gitignored'):
            for ign in ('.gitignore','.ignore','.rgignore'):
                fp=os.path.join(base,ign)
                if os.path.isfile(fp) and (ign!='.gitignore' or havegit):
                    try:
                        for line in Path(fp).read_text().splitlines():
                            if line and not line.startswith('#'):ignores.append((os.path.relpath(base,'.'),line))
                    except (OSError,UnicodeError):pass
        def ignored(path,isdir=False):
            matched=False
            for b,p in ignores:
                rel=os.path.relpath(path,b if b!='.' else '.')
                if rel.startswith('../'):continue
                neg=p.startswith('!');p=p[1:] if neg else p
                dironly=p.endswith('/');p=p.rstrip('/')
                if dironly and not isdir:continue
                if '/' not in p.strip('/'):
                    yes=any(fnmatch.fnmatchcase(c,p) for c in rel.split('/'))
                else:yes=glob_match(rel,p.lstrip('/'))
                if yes:matched=not neg
            return matched
        dirs[:]=[x for x in dirs if (opts.get('hidden') or not x.startswith('.')) and x!='.git' and not os.path.islink(os.path.join(base,x)) and (opts.get('gitignored') or not ignored(os.path.join(base,x),True))]
        for f in files:
            if not opts.get('hidden') and f.startswith('.'):continue
            path=os.path.normpath(os.path.join(base,f))
            if os.path.islink(path):continue
            if not opts.get('gitignored') and ignored(path):continue
            if lang and not f.endswith(extensions[lang]):continue
            if pattern and not glob_match(path,pattern):continue
            found.append(path)
    if opts.get('sorted'):found.sort()
    return found


def run(opts):
    if opts.get('help'):
        from helptext import LONG_HELP,SHORT_HELP
        sys.stdout.write(SHORT_HELP if opts.get('short-help') else LONG_HELP);return 0
    if opts.get('version'):print('srgn 0.14.1');return 0
    if opts.get('completions'):
        try:
            from completions import COMPLETIONS
            sys.stdout.write(COMPLETIONS[opts['completions']])
        except ImportError:pass
        return 0
    # Compile and validate before touching input files.
    regex=None if opts.get('literal-string') else Regex(opts['scope'])
    if opts['replacement'] is not None:opts['replacement']=unescape_replacement(opts['replacement'])
    specs=[]
    for lang,typ,val in opts['scopes']:
        if typ=='query-file':
            try:val=Path(val).read_text()
            except OSError as e:raise AppError('Error: I/O error: '+os_error(e)+'\n')
            typ='query'
        if typ=='query':
            from queries import compile_query
            compile_query(val)
        specs.append((lang,typ,val))
    opts['scopes']=specs
    opts['tty']=opts.get('stdout-detection')=='force-tty' or (opts.get('stdout-detection','auto')=='auto' and sys.stdout.isatty())
    if not opts['actions'] and not opts['search']:
        log('No actions specified, and not in search mode. Will return input unchanged, if any.')
    readable=stdin_readable(opts)
    if readable:
        if opts.get('glob'):log('Detected stdin, and request for files: will use stdin and ignore files.')
        try:text=sys.stdin.buffer.read().decode('utf-8')
        except UnicodeError:raise AppError('Error: I/O error: stream did not contain valid UTF-8\n')
        out,_,_=apply_text(text,opts,regex)
        sys.stdout.write(out);return 0
    paths=discover(opts)
    if not paths and opts.get('fail-no-files'):raise AppError('Error: No files found\n')
    anymatch=False
    for path in paths:
        try:data=Path(path).read_bytes()
        except OSError as e:raise AppError('Error: I/O error: '+os_error(e)+'\n')
        if b'\x00' in data:continue
        try:text=data.decode('utf-8')
        except UnicodeError:continue
        try:out,matched,new=apply_text(text,opts,regex,path,True)
        except AppError as e:
            if e.message.startswith('Error: Error applying: '):e.message=e.message.replace('Error: Error applying: ','Error: ',1)
            raise
        anymatch=anymatch or matched
        if opts['search'] or opts.get('dry-run'):
            if out:
                if opts['tty']:sys.stdout.write(path+'\n'+out+'\n')
                else:sys.stdout.write(out)
        elif out!=text:
            try:Path(path).write_bytes(out.encode('utf-8'))
            except OSError as e:raise AppError('Error: I/O error: '+os_error(e)+'\n')
            sys.stdout.write(path+'\n')
    if (opts.get('fail-none') or opts['search']) and not anymatch:
        raise AppError('Error: No input was in scope\n')
    return 0


def os_error(e):
    return (e.strerror or str(e))+' (os error '+str(e.errno)+')'


def main():
    try:
        opts=parse_args(sys.argv[1:]);status=run(opts)
    except AppError as e:
        sys.stderr.write(e.message);status=e.code
    except BrokenPipeError:status=0
    except OSError as e:
        sys.stderr.write('Error: I/O error: '+os_error(e)+'\n');status=1
    sys.exit(status)

if __name__=='__main__':main()
